#!/bin/bash
set -e
python3 - "$@" <<'PY'
import json
import re
import subprocess
import sys

SOCK = "/run/bench70948748/containerd/containerd.sock"
pid, out = sys.argv[1:3]


def cri(*args):
    r = subprocess.run(["sudo", "crictl", "--runtime-endpoint", "unix://" + SOCK, "--image-endpoint", "unix://" + SOCK, *args],
                       capture_output=True, text=True)
    return r


def record(d):
    labels = d["status"]["labels"]
    return {"container_id": d["status"]["id"], "pod_uid": labels["io.kubernetes.pod.uid"], "pod_namespace": labels["io.kubernetes.pod.namespace"],
            "pod_name": labels["io.kubernetes.pod.name"], "container_name": labels["io.kubernetes.container.name"], "init_pid": int(d["info"]["pid"])}



def ppid(p):
    raw = open("/proc/%d/stat" % p).read()
    return int(raw[raw.rindex(")") + 2:].split()[1])


firsts = {}
for c in json.loads(cri("ps", "-o", "json").stdout)["containers"]:
    d = json.loads(cri("inspect", "-o", "json", c["id"]).stdout)
    firsts[int(d["info"]["pid"])] = d
p, owner = int(pid), None
while p > 1:
    if p in firsts:
        owner = record(firsts[p])
        break
    p = ppid(p)
json.dump(owner, open(out, "w"))
PY
